  /** Wait for a terminal status on the owning uploader. Terminal errors, cancellation and an aborted request are returned without implying successful processing or stopped backend work. */
  waitForAssembly(input: AssemblyWorkflowOptions): Promise<AssemblyWorkflowResult> {
    return runAssemblyWorkflow(
      input,
      false,
      assemblyWorkflowPolicy,
      this.workflowOptions(),
      (signal) => this.getAssembly({ path: { assemblyId: input.assemblyId }, signal }),
      (options) => {
        const owner = new ContractClient(options)
        return {
          read: (signal) => owner.getAssembly({ path: { assemblyId: input.assemblyId }, signal }),
          cancel: (signal) =>
            owner.cancelAssembly({ path: { assemblyId: input.assemblyId }, signal }),
        }
      },
    )
  }
  /** Cancel once on the owning uploader, then wait for a terminal status. Terminal errors, cancellation and an aborted request are returned without implying successful processing or stopped backend work. */
  cancelAndWaitForAssembly(input: AssemblyWorkflowOptions): Promise<AssemblyWorkflowResult> {
    return runAssemblyWorkflow(
      input,
      true,
      assemblyWorkflowPolicy,
      this.workflowOptions(),
      (signal) => this.getAssembly({ path: { assemblyId: input.assemblyId }, signal }),
      (options) => {
        const owner = new ContractClient(options)
        return {
          read: (signal) => owner.getAssembly({ path: { assemblyId: input.assemblyId }, signal }),
          cancel: (signal) =>
            owner.cancelAssembly({ path: { assemblyId: input.assemblyId }, signal }),
        }
      },
    )
  }
  /** Upload one fixed-size file to an existing Assembly; persist its session before bytes are sent. Completion here means transferred bytes, not successful Assembly processing. */
  uploadAssemblyFile(input: AssemblyUploadOptions) {
    return runTusUpload(
      input,
      undefined,
      tusWorkflowPolicy,
      this.workflowOptions(),
      (assemblyId, signal) => this.getAssembly({ path: { assemblyId: assemblyId }, signal }),
      (kind, url, headers, body, signal) =>
        requestTus(this.workflowOptions(), tusWorkflowPolicy[kind], url, headers, body, signal),
    )
  }
  /** Resume the same file using a saved upload session and the server offset. Completion here means transferred bytes, not successful Assembly processing. */
  resumeAssemblyFile(input: ResumeAssemblyUploadOptions) {
    return runTusUpload(
      input,
      input.session,
      tusWorkflowPolicy,
      this.workflowOptions(),
      (assemblyId, signal) => this.getAssembly({ path: { assemblyId: assemblyId }, signal }),
      (kind, url, headers, body, signal) =>
        requestTus(this.workflowOptions(), tusWorkflowPolicy[kind], url, headers, body, signal),
    )
  }
